/**
 * Object storage (S3-compatible). Binaries live here, never in PostgreSQL and never permanently on a container's disk.
 *
 * Drivers:
 * - `s3`: any S3-compatible service. Required in staging/production (enforced by packages/config).
 * - `local`: a directory on this machine. Single-host development only (not shared across replicas).
 * - `memory`: in-process map. Tests only; supports fault injection.
 *
 * Keys are generated by the server only (see `assertSafeKey`). Credentials never leave the API process: browsers get
 * either `STORAGE_PUBLIC_BASE_URL/<key>` (CDN/public bucket) or the API's controlled media route.
 */
import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import { dirname, resolve, sep } from "node:path";
import {
  DeleteObjectCommand,
  GetObjectCommand,
  NoSuchKey,
  PutObjectCommand,
  S3Client,
} from "@aws-sdk/client-s3";
import type { AppConfig } from "@restaurant-platform/config";

export interface StoredObject {
  body: Buffer;
  contentType: string;
}

export interface PutOptions {
  contentType: string;
  cacheControl: string;
}

export interface ObjectStorage {
  readonly driver: AppConfig["STORAGE_DRIVER"];
  put(key: string, body: Buffer, opts: PutOptions): Promise<void>;
  /** Returns null when the object does not exist. */
  get(key: string): Promise<StoredObject | null>;
  /** Idempotent: deleting a missing object succeeds. */
  delete(key: string): Promise<void>;
  /** URL a browser uses to fetch the object (never signed, never carries credentials). */
  publicUrl(key: string): string;
}

/** Path served by the API's media route when no public base URL is configured. */
export const MEDIA_ROUTE_PREFIX = "/api/v1/public/media/";

// Lowercase prefix segment, then opaque segments of URL-safe characters. No "..", no leading slash, no backslashes.
const SAFE_KEY = /^[a-z0-9-]+(?:\/[A-Za-z0-9_-]+)*\/[A-Za-z0-9_-]+\.[a-z0-9]{2,5}$/;

export function assertSafeKey(key: string): void {
  if (key.length > 300 || !SAFE_KEY.test(key)) throw new Error("unsafe storage key");
}

function publicUrlFor(config: AppConfig, key: string): string {
  return config.STORAGE_PUBLIC_BASE_URL
    ? `${config.STORAGE_PUBLIC_BASE_URL}/${key}`
    : `${MEDIA_ROUTE_PREFIX}${key}`;
}

export function createObjectStorage(config: AppConfig): ObjectStorage {
  switch (config.STORAGE_DRIVER) {
    case "s3":
      return createS3Storage(config);
    case "local":
      return createLocalStorage(config, resolve(config.STORAGE_LOCAL_DIR));
    case "memory":
      return createMemoryStorage(config);
  }
}

// ---------------------------------------------------------------- s3

function createS3Storage(config: AppConfig): ObjectStorage {
  const bucket = config.STORAGE_BUCKET;
  if (!bucket) throw new Error("STORAGE_BUCKET is required");
  const client = new S3Client({
    region: config.STORAGE_REGION,
    ...(config.STORAGE_ENDPOINT ? { endpoint: config.STORAGE_ENDPOINT } : {}),
    forcePathStyle: config.STORAGE_FORCE_PATH_STYLE,
    ...(config.STORAGE_ACCESS_KEY_ID && config.STORAGE_SECRET_ACCESS_KEY
      ? {
          credentials: {
            accessKeyId: config.STORAGE_ACCESS_KEY_ID,
            secretAccessKey: config.STORAGE_SECRET_ACCESS_KEY,
          },
        }
      : {}),
    maxAttempts: 3,
  });
  return {
    driver: "s3",
    async put(key, body, opts) {
      assertSafeKey(key);
      await client.send(
        new PutObjectCommand({
          Bucket: bucket,
          Key: key,
          Body: body,
          ContentType: opts.contentType,
          CacheControl: opts.cacheControl,
          ContentLength: body.length,
        }),
      );
    },
    async get(key) {
      assertSafeKey(key);
      try {
        const res = await client.send(new GetObjectCommand({ Bucket: bucket, Key: key }));
        if (!res.Body) return null;
        return {
          body: Buffer.from(await res.Body.transformToByteArray()),
          contentType: res.ContentType ?? "application/octet-stream",
        };
      } catch (err) {
        if (err instanceof NoSuchKey) return null;
        throw err;
      }
    },
    async delete(key) {
      assertSafeKey(key);
      await client.send(new DeleteObjectCommand({ Bucket: bucket, Key: key }));
    },
    publicUrl: (key) => publicUrlFor(config, key),
  };
}

// ---------------------------------------------------------------- local (development only)

function createLocalStorage(config: AppConfig, root: string): ObjectStorage {
  const pathFor = (key: string): string => {
    assertSafeKey(key);
    const p = resolve(root, key);
    // Defence in depth on top of the key pattern: never leave the storage root.
    if (!p.startsWith(root + sep)) throw new Error("unsafe storage key");
    return p;
  };
  return {
    driver: "local",
    async put(key, body, opts) {
      const p = pathFor(key);
      await mkdir(dirname(p), { recursive: true });
      await writeFile(p, body);
      await writeFile(`${p}.type`, opts.contentType);
    },
    async get(key) {
      const p = pathFor(key);
      try {
        const [body, contentType] = await Promise.all([readFile(p), readFile(`${p}.type`, "utf8")]);
        return { body, contentType };
      } catch (err) {
        if ((err as NodeJS.ErrnoException).code === "ENOENT") return null;
        throw err;
      }
    },
    async delete(key) {
      const p = pathFor(key);
      await Promise.all([rm(p, { force: true }), rm(`${p}.type`, { force: true })]);
    },
    publicUrl: (key) => publicUrlFor(config, key),
  };
}

// ---------------------------------------------------------------- memory (tests)

export interface MemoryStorage extends ObjectStorage {
  readonly objects: Map<string, StoredObject>;
  /** Fault injection: return an Error to make the next matching operation fail, or null to proceed. */
  failWith: ((op: "put" | "get" | "delete", key: string) => Error | null) | null;
}

export function createMemoryStorage(config: AppConfig): MemoryStorage {
  const objects = new Map<string, StoredObject>();
  const storage: MemoryStorage = {
    driver: "memory",
    objects,
    failWith: null,
    put(key, body, opts) {
      assertSafeKey(key);
      const err = storage.failWith?.("put", key);
      if (err) return Promise.reject(err);
      objects.set(key, { body: Buffer.from(body), contentType: opts.contentType });
      return Promise.resolve();
    },
    get(key) {
      assertSafeKey(key);
      const err = storage.failWith?.("get", key);
      if (err) return Promise.reject(err);
      return Promise.resolve(objects.get(key) ?? null);
    },
    delete(key) {
      assertSafeKey(key);
      const err = storage.failWith?.("delete", key);
      if (err) return Promise.reject(err);
      objects.delete(key);
      return Promise.resolve();
    },
    publicUrl: (key) => publicUrlFor(config, key),
  };
  return storage;
}
